#!/usr/bin/env bash
# Question 1: DaemonSet ${Q1_DS} on every node. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

kubectl create namespace "${Q1_NS}" >/dev/null 2>&1 || kubectl get namespace "${Q1_NS}" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q1_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl -n "${Q1_NS}" delete daemonset "${Q1_DS}" --ignore-not-found --wait=true >/dev/null
: "${Q1_NS}" "${Q1_STS}" "${Q1_DS}"
